\"\"\"Minimal, standard-library-only client for OpenAI's Responses API.

Privacy defaults:
- The API key is read from the OPENAI_API_KEY environment variable (never hard-coded).
- Requests are sent with "'``"store": false`` so responses are not stored for later retrieval.
- Prompts and outputs are never logged or written to disk by this module.
- Error messages exclude the prompt and API key.

Example:
    from openai_client import send_prompt
    print(send_prompt("Summarize the benefits of unit tests."))

CLI:
    OPENAI_API_KEY=... python3 openai_client.py "Your prompt"
    echo "Your prompt" | python3 openai_client.py
"""

from __future__ import annotations

import json
import os
import ssl
import sys
import urllib.error
import urllib.request
from typing import Any, Optional

API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"
DEFAULT_TIMEOUT = 60.0


class OpenAIError(RuntimeError):
    """Raised when the API request fails."""

    def __init__(self, message: str, status: Optional[int] = None) -> None:
        super().__init__(message)
        self.status = status


def _get_api_key(api_key: [REDACTED_SECRET] -> str:
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError("No API key provided. Set the OPENAI_API_KEY environment variable.")
    return key


def create_response(
    prompt: str,
    *,
    model: Optional[str] = None,
    instructions: Optional[str] = None,
    api_key: [REDACTED_SECRET] = None,
    store: bool = False,
    timeout: float = DEFAULT_TIMEOUT,
    extra: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    """Send a text prompt to the Responses API and return the parsed JSON response."""
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")

    payload: dict[str, Any] = {
        "model": model or os.environ.get("OPENAI_MODEL", DEFAULT_MODEL),
        "input": prompt,
        "store": store,
    }
    if instructions:
        payload["instructions"] = instructions
    if extra:
        payload.update(extra)

    headers = {
        "Authorization": f"Bearer {_get_api_key(api_key)}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    organization = os.environ.get("OPENAI_ORG_ID")
    if organization:
        headers["OpenAI-Organization"] = organization
    project = os.environ.get("OPENAI_PROJECT_ID")
    if project:
        headers["OpenAI-Project"] = project

    request = urllib.request.Request(
        API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers=headers,
        method="POST",
    )
    context = ssl.create_default_context()

    try:
        with urllib.request.urlopen(request, timeout=timeout, context=context) as response:
            body = response.read().decode("utf-8")
    except urllib.error.HTTPError as error:
        raise OpenAIError(
            f"OpenAI API error {error.code}: {_error_message(error)}", status=error.code
        ) from None
    except urllib.error.URLError as error:
        raise OpenAIError(f"Network error contacting OpenAI API: {error.reason}") from None
    except TimeoutError:
        raise OpenAIError("Request to OpenAI API timed out") from None

    try:
        return json.loads(body)
    except json.JSONDecodeError:
        raise OpenAIError("OpenAI API returned invalid JSON") from None


def _error_message(error: urllib.error.HTTPError) -> str:
    try:
        data = json.loads(error.read().decode("utf-8"))
        return str(data.get("error", {}).get("message") or error.reason)
    except Exception:
        return str(error.reason)


def extract_text(response: dict[str, Any]) -> str:
    """Return the concatenated output text from a Responses API result."""
    if isinstance(response.get("output_text"), str):
        return response["output_text"]
    parts: list[str] = []
    for item in response.get("output", []) or []:
        if item.get("type") != "message":
            continue
        for content in item.get("content", []) or []:
            if content.get("type") == "output_text" and isinstance(content.get("text"), str):
                parts.append(content["text"])
            elif content.get("type") == "refusal" and isinstance(content.get("refusal"), str):
                parts.append(content["refusal"])
    return "".join(parts)


def send_prompt(prompt: str, **kwargs: Any) -> str:
    """Send a private text prompt and return the model'"'s text output.\"\"\"
    response = create_response(prompt, **kwargs)
    text = extract_text(response)
    if response.get(\"status\") not in (None, \"completed\") and not text:
        details = response.get(\"incomplete_details\") or response.get(\"error\") or {}
        reason = details.get(\"reason\") or details.get(\"message\") or response.get(\"status\")
        raise OpenAIError(f\"Response not completed: {reason}\")
    return text


def main(argv: Optional[list[str]] = None) -> int:
    import argparse

    parser = argparse.ArgumentParser(description=\"Send a private prompt to the OpenAI Responses API.\")
    parser.add_argument(\"prompt\", nargs=\"?\", help=\"Prompt text (reads stdin if omitted)\")
    parser.add_argument(\"-m\", \"--model\", help=f\"Model name (default: "'$OPENAI_MODEL or {DEFAULT_MODEL})")
    parser.add_argument("-i", "--instructions", help="Optional system/developer instructions")
    parser.add_argument("-t", "--timeout", type=float, default=DEFAULT_TIMEOUT)
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    try:
        print(
            send_prompt(
                prompt,
                model=args.model,
                instructions=args.instructions,
                timeout=args.timeout,
            )
        )
    except (OpenAIError, ValueError) as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
